ext('c12_hin_ch17',[
C("📜","भक्तमाल क्या है",["भक्तों की जीवन-गाथाओं का संग्रह","छप्पय छंद में रचित","लगभग 200 से अधिक भक्तों का वर्णन","प्रियादास की टीका"],"नाभादास की भक्तमाल हिंदी भक्ति साहित्य का एक अनोखा ग्रंथ है। भक्तमाल का अर्थ है भक्तों की माला, यानी बहुत से भक्तों के नाम और गुणों को एक सूत्र में पिरोना। इसमें दो सौ से अधिक भक्तों का परिचय संक्षेप में छप्पय छंद में दिया गया है, जिनमें संत, कवि और साधारण भक्त भी शामिल हैं। बाद में प्रियादास ने इस पर विस्तृत टीका लिखी, जिससे यह और भी लोकप्रिय हुई। भक्तमाल एक तरह से भक्तिकाल के संतों का परिचय-कोश है। इस पाठ में उसके कबीर और सूरदास वाले छप्पय पढ़े जाते हैं।"),
C("✍️","नाभादास का परिचय",["सोलहवीं सदी के अंत के कवि","रामानंदी संप्रदाय के भक्त","अग्रदास के शिष्य","भक्तमाल उनकी प्रमुख रचना"],"नाभादास भक्तिकाल के कवि हैं और माना जाता है कि वे सोलहवीं सदी के अंत और सत्रहवीं सदी के आरंभ में हुए। वे रामानंदी संप्रदाय से जुड़े थे और संत अग्रदास के शिष्य थे। उनके जीवन के बारे में कई कथाएँ प्रचलित हैं, पर प्रमुख बात यह है कि उन्होंने भक्तों का सम्मान करते हुए उनका गुणगान किया। उनकी प्रमुख रचना भक्तमाल है। हिंदी साहित्य के इतिहास में यह इसलिए भी महत्वपूर्ण है, क्योंकि इससे उस समय के अनेक संतों और कवियों के बारे में महत्वपूर्ण सूचनाएँ मिलती हैं।"),
C("📐","छप्पय छंद का स्वरूप",["छह चरणों का मात्रिक छंद","पहले चार चरण रोला","अंतिम दो चरण उल्लाला","मिश्रित छंद"],"इस पाठ का छंद छप्पय है। छप्पय का अर्थ है छह पंक्तियों वाला। यह एक मिश्रित छंद है, जिसमें पहले चार चरण रोला छंद के होते हैं और अंतिम दो चरण उल्लाला छंद के। इस मेल से कविता में गंभीरता भी आती है और प्रवाह भी। छप्पय का प्रयोग अकसर प्रशंसा और वीर रस वाली कविताओं में होता है, क्योंकि उसकी गति प्रभावशाली होती है। परीक्षा में पूछा जा सकता है कि छप्पय कितने चरणों का होता है और उसमें कौन से दो छंद मिले होते हैं। उत्तर है छह चरण, रोला और उल्लाला।"),
C("🧵","कबीर का स्वरूप",["निर्भीक संत कवि","पाखंड और आडंबर का विरोध","हिंदू-मुस्लिम एकता के पक्षधर","सहज भक्ति और सच्चाई"],"पहले छप्पय में नाभादास कबीर की प्रशंसा करते हैं। कबीर निर्भीक संत थे, जिन्होंने धर्म के नाम पर होने वाले पाखंड और ऊँच-नीच का खुलकर विरोध किया। वे हिंदू और मुसलमान, दोनों को उनकी कमियाँ बताने से नहीं डरे और सबको सच्ची भक्ति तथा मानवता की ओर बुलाया। नाभादास कहते हैं कि कबीर ने भक्ति को बाहरी दिखावे से ऊपर रखा। कबीर की यह निडरता आज भी प्रासंगिक है, क्योंकि अंधविश्वास और भेदभाव अब भी समाज में दिखते हैं।"),
C("🎵","सूरदास की काव्य प्रतिभा",["सूर की कविता की श्रेष्ठता","उक्तियों में चमत्कार","अर्थ की गहराई","कृष्ण लीला का मधुर वर्णन"],"दूसरे छप्पय में सूरदास की कविता की प्रशंसा की गई है। नाभादास कहते हैं कि सूर की कविता बहुत सुंदर है, जिसकी उक्तियाँ यानी कथन चमत्कारपूर्ण हैं और जिनमें अर्थ की गहराई है। सूर ने कृष्ण की लीलाओं का इतना मधुर वर्णन किया कि सुनने वाले मंत्रमुग्ध हो जाते हैं। यहाँ एक बात ध्यान रखिए कि सूरदास कृष्ण भक्ति शाखा के कवि हैं और कबीर निर्गुण शाखा के। फिर भी नाभादास ने दोनों का समान आदर के साथ वर्णन किया है, यह उनकी उदार दृष्टि का प्रमाण है।"),
C("⚖️","कबीर और सूर की तुलना",["कबीर: निर्गुण, सुधारक","सूर: सगुण, कृष्ण भक्त","कबीर: सधुक्कड़ी भाषा","सूर: ब्रजभाषा"],"अब दोनों कवियों की तुलना कीजिए। कबीर निर्गुण संत थे, जो निराकार ईश्वर को मानते थे और समाज सुधार पर ज़ोर देते थे। सूरदास सगुण भक्त थे, जो कृष्ण के साकार रूप की उपासना करते थे और उनके बाल रूप का मनमोहक वर्णन करते थे। कबीर की भाषा सधुक्कड़ी, यानी कई बोलियों का मेल थी और सूर की भाषा मधुर ब्रज। कबीर की शैली तीखी और उपदेश की थी, जबकि सूर की कोमल और भावपूर्ण। पर दोनों का लक्ष्य एक था, मनुष्य को ईश्वर की भक्ति की ओर ले जाना।"),
C("🌿","भक्ति आंदोलन का प्रभाव",["जाति-पाँति का विरोध","भाषा का लोकतंत्रीकरण","स्त्री और निम्न वर्ग की भागीदारी","साहित्य में मानवीय मूल्य"],"नाभादास जिन कवियों का वर्णन करते हैं, वे भक्ति आंदोलन की देन हैं। इस आंदोलन ने समाज में कई बदलाव किए। इसने जाति-पाँति और ऊँच-नीच का विरोध किया। संस्कृत की जगह जनभाषा में कविता लिखी गई, जिससे साधारण लोग भी ईश्वर और साहित्य से जुड़ सके। इसमें स्त्रियों और समाज के पिछड़े वर्गों की भागीदारी भी बढ़ी। भक्तिकाल को हिंदी साहित्य का स्वर्णयुग इसीलिए कहा जाता है। इस पाठ से हम समझते हैं कि भक्ति केवल पूजा नहीं, एक सामाजिक चेतना भी थी।"),
C("🔤","मुख्य शब्द और अर्थ",["पाखंड: दिखावटी धर्म","उक्ति: कथन","चमत्कार: विलक्षण बात","माला: क्रमबद्ध संग्रह"],"आइए पाठ के कुछ शब्द याद कर लें। पाखंड का अर्थ है दिखावे वाला धर्म या आचरण। उक्ति यानी कथन या कहने की शैली। चमत्कार यानी असाधारण या आश्चर्यजनक बात। माला यानी क्रम से जुड़ा हुआ संग्रह, जैसे भक्तमाल। निर्भीक यानी जिसे कोई डर न हो। इन शब्दों से अपने वाक्य बनाइए और कॉपी में लिखिए। परीक्षा में कई बार शब्दार्थ और वाक्य प्रयोग पूछे जाते हैं, इसलिए पाठ के शब्दों को अपनी भाषा में प्रयोग करने की आदत डालिए।"),
C("📘","व्याख्या लिखने का तरीक़ा",["प्रसंग लिखिए","भाव सरल भाषा में","विशेष: छंद और भाषा","सार एक वाक्य में"],"छप्पय की व्याख्या लिखते समय पहले प्रसंग में लिखिए कि यह पंक्तियाँ नाभादास की भक्तमाल से ली गई हैं, जिसमें कबीर या सूर की प्रशंसा है। फिर पंक्ति के अर्थ को सरल भाषा में समझाइए। विशेष में लिखिए कि छंद छप्पय है, भाषा ब्रज मिश्रित है और शैली प्रशंसात्मक है। अंत में एक वाक्य में सार दीजिए। साफ़ अक्षरों और अलग-अलग अनुच्छेदों में लिखिए, क्योंकि जाँचने वाले को उत्तर आसानी से दिखना चाहिए।"),
C("🏞️","भक्ति परंपरा और बिहार",["कबीर की बिहार में बहुत प्रसिद्धि","कबीरपंथी परंपरा","छठ, कीर्तन और भजन","लोकगीतों में भक्ति"],"बिहार में भी भक्ति परंपरा गहरी है। कबीर के भजन यहाँ गाँव-गाँव में गाए जाते हैं और कबीरपंथी परंपरा के कई मठ और अनुयायी बिहार में हैं। इसी तरह कृष्ण भक्ति के पद, जैसे सूर के, कीर्तन-मंडलियों में गाए जाते हैं। छठ, होली और जन्माष्टमी के गीतों में भी वही भक्ति और लोकभाव है। इसलिए जब आप यह पाठ पढ़ें, तो उसे अपने आसपास के भजन-कीर्तन से जोड़कर देखिए। इससे साहित्य सिर्फ़ किताब का नहीं, जीवन का हिस्सा लगेगा।"),
C("🧠","प्रशंसा काव्य की विशेषताएँ",["गुणों का वर्णन","आदर और श्रद्धा का भाव","संक्षिप्त पर प्रभावशाली","भक्तों को प्रेरणा"],"नाभादास की ये रचनाएँ प्रशंसा काव्य के उदाहरण हैं। प्रशंसा काव्य में किसी व्यक्ति के गुणों का आदर और श्रद्धा से वर्णन होता है। इसकी विशेषता है कि यह संक्षिप्त होते हुए भी असरदार होता है। छप्पय की सीमित पंक्तियों में ही नाभादास कबीर और सूर के मुख्य गुण पकड़ लेते हैं। ऐसे काव्य का एक उद्देश्य यह भी है कि पढ़ने वाले उन भक्तों से प्रेरणा लें। हम भी अपने गुरुजनों और आदर्श व्यक्तियों के बारे में पाँच वाक्य ऐसी ही प्रशंसात्मक शैली में लिखकर देख सकते हैं।"),
C("📌","पाठ का सार",["नाभादास: भक्तमाल के रचयिता","पहला छप्पय: कबीर की प्रशंसा","दूसरा छप्पय: सूर की प्रशंसा","संदेश: भक्तों का आदर और भक्ति की महत्ता"],"अब पाठ का सार दोहराइए। नाभादास भक्तमाल के रचयिता हैं। इस पाठ के पहले छप्पय में उन्होंने कबीर के निर्भीक और पाखंड-विरोधी स्वभाव की प्रशंसा की है। दूसरे छप्पय में सूरदास की श्रेष्ठ काव्य प्रतिभा और चमत्कारपूर्ण उक्तियों का वर्णन किया है। छंद छप्पय है, जिसमें छह चरण होते हैं। मूल संदेश है कि सच्ची भक्ति और सच्चे भक्तों का आदर करना चाहिए। इसे पाँच वाक्यों में अपने शब्दों में लिखकर देखिए।"),
C("❓","संभावित परीक्षा प्रश्न",["नाभादास का परिचय","भक्तमाल क्या है","छप्पय छंद की विशेषता","कबीर की प्रशंसा में क्या कहा"],"परीक्षा के प्रश्न देखिए। पहला, नाभादास का परिचय दीजिए। उत्तर, भक्तिकाल के कवि, रामानंदी संप्रदाय, अग्रदास के शिष्य, भक्तमाल के रचयिता। दूसरा, भक्तमाल क्या है? उत्तर, भक्तों की जीवनियों का छप्पय छंद में संग्रह। तीसरा, छप्पय की विशेषता? उत्तर, छह चरणों वाला मिश्रित छंद, चार रोला और दो उल्लाला। चौथा, कबीर के बारे में क्या कहा गया? उत्तर, उनकी निर्भीकता और पाखंड-विरोध की प्रशंसा। उत्तर पूरे वाक्य में लिखिए।"),
Q("कबीर और सूरदास की भक्ति में क्या मुख्य अंतर है?","कबीर निर्गुण (निराकार) भक्ति और समाज-सुधार के कवि हैं, सूरदास सगुण (साकार) कृष्ण भक्ति के कवि हैं।","एक सोचने वाला प्रश्न। कबीर और सूरदास की भक्ति में क्या मुख्य अंतर है? सोचिए। ... कबीर निर्गुण यानी निराकार भक्ति और समाज सुधार के कवि हैं, जबकि सूरदास सगुण यानी साकार कृष्ण भक्ति के कवि हैं। दोनों का लक्ष्य एक है, पर रास्ते अलग हैं।"),
],7)
